                stmt.setDate(1, Date.valueOf(date));
                stmt.setDate(2, Date.valueOf(date));
                stmt.setString(3, status.name());
                try (ResultSet rs = stmt.executeQuery()) {
                    while (rs.next()) {
                        reservations.add(mapRow(rs));
